-- Flying Cobra · 0005 animal seed
-- The whole roster plus the rules that place each animal in a bag (docs/ALGORITHMS.md §3, §6–§9).
-- Idempotent: animals upsert on slug; seed rules are wiped (note like 'seed:%') and re-inserted.
-- animal_counters are created by the animals_counter trigger — never insert them here.
--
-- Palettes are per FAMILY so same-family cards look related:
--   swift amber/sand · steady forest green · calm dusk lavender · gentle terracotta
--   time indigo night (night bag) / dawn peach (dawn bag) · explorer ochre · regional teal
--   weekly deep crimson · migratory sky blue · secret iridescent purple · national saffron

-- ---------- animals ----------
with pal(family, bag, palette) as (values
  ('swift',     'default', '{"bg":"#F4A940","fg":"#3B2208","accent":"#FFE3A8"}'::jsonb),
  ('steady',    'default', '{"bg":"#2F6B3A","fg":"#EAF5E6","accent":"#9BD47F"}'::jsonb),
  ('calm',      'default', '{"bg":"#6E5B9A","fg":"#F6F1FF","accent":"#D6C6F2"}'::jsonb),
  ('gentle',    'default', '{"bg":"#B35A3C","fg":"#FFF1E8","accent":"#F2B48F"}'::jsonb),
  ('time',      'night',   '{"bg":"#1F2459","fg":"#E8E9FF","accent":"#F9C9A8"}'::jsonb),
  ('time',      'dawn',    '{"bg":"#F7C9A6","fg":"#2A2F6B","accent":"#1F2459"}'::jsonb),
  ('explorer',  'default', '{"bg":"#C9962B","fg":"#2E2208","accent":"#F5E2A8"}'::jsonb),
  ('regional',  'default', '{"bg":"#1F7A78","fg":"#E6FAF8","accent":"#8FDBD6"}'::jsonb),
  ('weekly',    'default', '{"bg":"#7A1430","fg":"#FFE9EE","accent":"#F2A3B5"}'::jsonb),
  ('migratory', 'default', '{"bg":"#4FA3E0","fg":"#0F2A44","accent":"#DDF0FF"}'::jsonb),
  ('secret',    'default', '{"bg":"#5B2A8C","fg":"#F7ECFF","accent":"#C77DFF"}'::jsonb),
  ('national',  'default', '{"bg":"#FF9933","fg":"#3B1F00","accent":"#FFE0B3"}'::jsonb)
),
a(slug, code, name, family, bag, rarity, flavour_line, encyclopedia, is_secret, sort_order) as (values

-- ===== swift (speed band P ≥ 0.60) =====
('chinkara','CHK','Chinkara','swift','default','common','the desert dancer',
 '{"facts":["Can go for long stretches without drinking, drawing moisture from dew and the plants it eats","Both sexes carry ringed horns; a male''s can reach 25–30 cm","Protected for centuries by the Bishnoi communities of Rajasthan, who treat the gazelle as kin"],"habitat":"arid plains, thorn scrub and dunes","size":"about 65 cm at the shoulder, around 23 kg","superpower":"lightness that turns sand into a running track","india_note":"the Indian gazelle of the Thar — Rajasthan, Gujarat, Madhya Pradesh and the Deccan drylands"}',
