 false, 21),
('nilgai','NLG','Nilgai','steady','default','uncommon','the blue bull of the plains',
 '{"facts":["The largest antelope in Asia — bulls can top 250 kg","Only adult males turn the blue-grey that gives the animal its name; females and young stay tawny","Herds return to the same communal dung piles, a rare habit among antelopes"],"habitat":"open scrub, farmland and dry forest","size":"1.2–1.5 m at the shoulder, 100–290 kg","superpower":"a powerful, ground-eating trot","india_note":"common across the northern plains; its cow-like name has long earned it protection"}',
 false, 22),
('dhole','DHL','Dhole','steady','default','uncommon','the pack hunter',
 '{"facts":["Hunts in packs of five to twelve and coordinates with whistles rather than howls","Can bring down prey such as sambar that weigh ten times as much as a single dhole","Pups eat first at a kill, and the pack regurgitates food for them"],"habitat":"deciduous and evergreen forest","size":"about 90 cm long, 12–20 kg","superpower":"teamwork that never breaks stride","india_note":"the Asiatic wild dog; strongholds in the Western Ghats, central India and the northeast"}',
 false, 23),
('indian-wolf','WLF','Indian Wolf','steady','default','rare','the grassland ghost',
 '{"facts":["Genomic studies place it among the oldest living wolf lineages","Smaller and thinner-coated than northern grey wolves, built for heat rather than snow","Lives in open grassland and scrub, hunting hare, rodents and blackbuck in small packs"],"habitat":"grassland, scrub and semi-arid plains","size":"60–70 cm at the shoulder, 20–30 kg","superpower":"a trot that can go on for hours","india_note":"only a few thousand remain, in places like Nannaj, Kutch and the Deccan grasslands"}',
 false, 24),
('leopard','LPD','Leopard','steady','default','epic','the shadow that walks anywhere',
 '{"facts":["Hauls kills heavier than itself up into trees to keep them from hyenas and tigers","The most adaptable big cat — leopards live inside Mumbai''s Sanjay Gandhi National Park","The 2022 national estimate counted around 13,800 leopards in India"],"habitat":"forest, scrub, rocky hills and city edges","size":"45–80 cm at the shoulder, 30–70 kg","superpower":"silent strength that fits any landscape","india_note":"found from the Himalayan foothills to the Western Ghats; the black panther is a dark-coated leopard"}',
