insert into animals(slug, code, name, family, rarity, flavour_line, encyclopedia, art, palette, is_secret, sort_order)
select a.slug, a.code, a.name, a.family, a.rarity::rarity_t, a.flavour_line, a.encyclopedia::jsonb,
       jsonb_build_object('baby',  'card-art/' || a.slug || '/baby.png',
                          'young', 'card-art/' || a.slug || '/young.png',
                          'adult', 'card-art/' || a.slug || '/adult.png'),
       pal.palette, a.is_secret, a.sort_order
from a
join pal on pal.family = a.family and pal.bag = a.bag
on conflict (slug) do update set
  code         = excluded.code,
  name         = excluded.name,
  family       = excluded.family,
  rarity       = excluded.rarity,
  flavour_line = excluded.flavour_line,
  encyclopedia = excluded.encyclopedia,
  art          = excluded.art,
  palette      = excluded.palette,
  is_secret    = excluded.is_secret,
  sort_order   = excluded.sort_order,
  is_active    = true;

-- ---------- rules ----------
delete from animal_rules where note like 'seed:%';

