) as r(slug, scope, tier, predicates, weight, ftg, rp)
join animals an on an.slug = r.slug;

-- ---------- sanity ----------
do $$ begin
  assert (select count(*) from animals) >= 80, 'animal seed incomplete';
  assert (select count(*) from animal_rules where note like 'seed:%') >= 100, 'rule seed incomplete';
  assert not exists (select 1 from animals a where not exists (select 1 from animal_rules r where r.animal_id = a.id)),
    'every animal needs at least one rule';
  assert not exists (select 1 from regions g where g.kind in ('state','ut')
                     and not exists (select 1 from animal_rules r where r.scope = 'monthly' and r.predicates->'region_codes' ? g.code)),
    'every state/UT needs a regional animal';
end $$;
